259:         public void FindReferencePoint()
260:         {
261:             bool bFlag = false;
262:             AKRS.WM.Position lastRefPos = new AKRS.WM.Position();
263:             AKRS.WM.Position currentPosition = this.WaferMapII.CurrentPosition;
264:             this.SetWaferMapSpacing();
265: 
266:             AKRS.WM.ReferencePoint[] referencePoints = this.WaferMapII.GetCopyOfReferencePoints();
267:             if (referencePoints.Length == 0)
268:             {
269:                 //throw new Exception($"The list of reference points is empty!");
270:                 throw new Exception($"参考点列表为空！");
271:             }
272: 
273:             // 晶圆图上前进到参考点1的位置
274:             this.WaferMapII.ForwardToPosition(referencePoints[0].Position);
275:             for (int i = 0; i < referencePoints.Length; i++)
276:             {
277:                 if (i == 0)
278:                 {
279:                     this.WaferMapII.StartAsyncSeekingPathBetweenTwoPoints(referencePoints[0].Position, referencePoints[i].Position);
280:                 }
281:                 else
282:                 {
283:                     this.WaferMapII.StartAsyncSeekingPathBetweenTwoPoints(referencePoints[i - 1].Position, referencePoints[i].Position);
284:                 }
285: 
286:                 // 等待查找路径结束
287:                 AKRS.WM.SearchResult wmSearchResult;
288:                 while (!this.WaferMapII.WaitForAsyncResultBetweenTwoPoints(0, out wmSearchResult))
289:                 {
290:                 }
291: 
292:                 if (wmSearchResult != AKRS.WM.SearchResult.Found)
293:                 {
294:                     if (wmSearchResult == AKRS.WM.SearchResult.NoResource)
295:                     {
296:                         //throw new Exception($"Failed to find reference point, wafer chart could not find path!");
297:                         throw new Exception($"查找参考点失败, 晶圆图没有发现路径！");
298:                     }
299:                     else
300:                     {
301:                         //throw new Exception($"Failed to find reference point!");
302:                         throw new Exception($"查找参考点失败！");
303:                     }
304:                 }
305: 
306:                 AKRS.WM.Info info;
307:                 do
308:                 {
309:                     #region 逐个搜索到参考点
310: 
311:                     info = this.WaferMapII.GetNextPositionInfoAndForwardToBetweenTwoPoints();
312:                     AKRSPoint3D currentDiePos = WaferSubModule.GetInstance().PointConvertAkrsPoint3D(info.PhysicalCoordinates);
313:                     WaferSubController.GetInstance().WaferTableController.MoveWaferTableToG0PosWithSearch(currentDiePos);
314: 
315:                     // 拍照定位并获取相机结果
316:                     (bool isSucceed, MatchResult[] matchResults) result = this.MatchResult();
317:                     if (!result.isSucceed && info.IsSpringboard)
318:                     {
319:                         currentDiePos = this.WaferTableRealPositionToG0;
320:                     }
321:                     else if (result.isSucceed)
322:                     {
323:                         AKRSPoint3D[] offset = this.MatchResultToWorld(result.matchResults);
324:                         currentDiePos.X = this.WaferTableRealPositionToG0.X - offset[0].X;
325:                         currentDiePos.Y = this.WaferTableRealPositionToG0.Y - offset[0].Y;
326: 
327:                         WaferSubController.GetInstance().WaferTableController.MoveWaferTableToG0PosWithSearch(currentDiePos);
328:                     }
329: 
330:                     // 非跳板是参考点
331:                     if (!info.IsSpringboard)
332:                     {
333:                         currentDiePos.X *= 1000;
334:                         currentDiePos.Y *= 1000;
335:                         this.WaferMapII.SetReferenceCoordinates(referencePoints[i], currentDiePos.ToPoint());
336:                         Position wtMap = info.Position;
337:                         AKRSPoint3D wt = this.WaferTableRealPositionToG0;
338:                         //AKRSXtraMessageBox.Show("参考点坐标(" + wtMap.Row + "," + wtMap.Column + ") 电机位置：X:" + wt.X + " Y:" + wt.Y);
339:                     }
340:                     else
341:                     {
342:                         currentDiePos.X *= 1000;
343:                         currentDiePos.Y *= 1000;
344:                         this.WaferMapII.SetPhysicalCoordinate(info.Position, currentDiePos.ToPoint());
345:                     }
346:                     #endregion
347:                 }
348:                 while (info.IsSpringboard);
349:             }
350: 
351:             bFlag = true;
352:             lastRefPos = referencePoints.Last().Position;
353: 
354:             this.WaferMapII.ForwardToPosition(currentPosition);
355: 
356:             // 动作完成标志
357:             if (bFlag)
358:             {
359:                 this.WaferMapII.SetCursorPosition(lastRefPos);
360:             }
361:         }

