374:             {
375:                 //throw new Exception($"The list of reference points is empty!");
376:                 throw new Exception($"参考点列表为空！");
377:             }
378: 
379:             AKRS.WM.Info info;
380:             #region 带多批次功能的晶圆图
381: 
382:             AKRS.WM.Position referablePoint = this.WaferMapII.FindNearestReferablePoint(
383:                 currentPosition,
384:                 out int xReferablePoint,
385:                 out int yReferablePoint);
386:             this.WaferMapII.StartAsyncSeekingPathBetweenTwoPoints(referablePoint, currentPosition);
387: 
388:             #endregion
389: 
390:             // 等待查找路径结束
391:             AKRS.WM.SearchResult wmSearchResult;
392:             while (!this.WaferMapII.WaitForAsyncResultBetweenTwoPoints(0, out wmSearchResult))
393:             {
394:             }
395: 
396:             if (wmSearchResult != AKRS.WM.SearchResult.Found)
397:             {
398:                 if (wmSearchResult == AKRS.WM.SearchResult.NoResource)
399:                 {
400:                     //throw new Exception($"Failed to find reference point, wafer chart could not find path!");
401:                     throw new Exception($"查找参考点失败, 晶圆图没有发现路径！");
402:                 }
403:                 else
404:                 {
405:                     //throw new Exception($"Failed to find reference point!");
406:                     throw new Exception($"查找参考点失败！");
407:                 }
408:             }
409: 
410:             do
411:             {
412:                 #region 逐个搜索到参考点
413: 
414:                 info = this.WaferMapII.GetNextPositionInfoAndForwardToBetweenTwoPoints();
415: 
416:                 this.WaferMapII.SetCursorPosition(info.Position);
417: 
418:                 AKRSPoint3D currentDiePos = WaferSubModule.GetInstance().PointConvertAkrsPoint3D(info.PhysicalCoordinates);
419: 
420:                 WaferSubController.GetInstance().WaferTableController.MoveWaferTableToG0PosWithSearch(currentDiePos);
421: 
422:                 // 拍照定位并获取相机结果
423:                 (bool isSucceed, MatchResult[] matchResults) result = this.MatchResult();
424:                 if (!result.isSucceed && info.IsSpringboard)
425:                 {
426:                     currentDiePos = this.WaferTableRealPositionToG0;
427:                 }
428:                 else if (result.isSucceed)
429:                 {
430:                     AKRSPoint3D[] offset = this.MatchResultToWorld(result.matchResults);
431:                     currentDiePos.X = this.WaferTableRealPositionToG0.X - offset[0].X;
432:                     currentDiePos.Y = this.WaferTableRealPositionToG0.Y - offset[0].Y;
433: 
434:                     WaferSubController.GetInstance().WaferTableController.MoveWaferTableToG0PosWithSearch(currentDiePos);
435:                 }
436: 
437:                 currentDiePos.X *= 1000;
438:                 currentDiePos.Y *= 1000;
439:                 this.WaferMapII.SetPhysicalCoordinate(info.Position, currentDiePos.ToPoint());
440:                 #endregion
441:             }
442:             while (info.Position != currentPosition);
443: 
444:             Position wtMap = info.Position;
445:             AKRSPoint3D wt = this.WaferTableRealPositionToG0;
446:             //AKRSXtraMessageBox.Show("起点坐标(" + wtMap.Row + "," + wtMap.Column + ") 电机位置：X:" + wt.X + " Y:" + wt.Y);

