201:         public bool IsAllowTaskClosed()
202:         {
203:             this.WorkTasks = new List<Task>();
204: 
205:             // 点胶线程
206:             if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
207:             {
208:                 this.WorkTasks.Add(System1Domain.GetInstance().DispenseWorkTask.DispenseTask);
209:             }
210: 
211:             this.WorkTasks.Add(WaferSystemDomain.GetInstance().WaferSubSystemTask.waferSubTask);
212:             this.WorkTasks.Add(System2Domain.GetInstance().BondTask.BondWorkTask);
213:             this.WorkTasks.Add(System2Domain.GetInstance().SlideFluxerTask.SlideFluxTask);
214:             this.WorkTasks.Add(WaferSystemDomain.GetInstance().FlipTask.FlipTableTask);
215: 
216:             #region 流道
217: 
218:             // 送板机传到上料皮带
219:             this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferAutoLoaderToLoadingBeltTask);
220: 
221:             // 上料皮带传到点胶
222:             this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferLoadBeltToDispense1Task);
223: 
224:             // 上料仓传到点胶
225:             this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferLoaderBinToDispense1Task);
226: 
227:             // 点胶1传到点胶2 
228:             this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferDispense1ToDispense2Task);
229: 
230:             // 点胶2 传到Bond
231:             this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferDispenseToBondTask);
232: 
233:             // Bond传到下料等待
234:             this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferBondToWaitingUnloadTask);
235: 
236:             // 下料等待传到下料皮带
237:             this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferWaitingUnloadToUnloadBeltTask);
238: 
239:             // 下料等待传到下料仓
240:             this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferWaitingUnloadToUnloadBinTask);
241: 
242:             // 下料皮带到送板机
243:             this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferUnloadBeltToAutoUnloaderTask);
244: 
245:             // 上料仓
246:             this.WorkTasks.Add(TransportDomain.GetInstance().LoaderTask.loaderTask);
247: 
248:             // 下料仓
249:             this.WorkTasks.Add(TransportDomain.GetInstance().UnloaderTask.unloaderTask);
250: 
251:             #endregion
252: 
253:             foreach (Task task in this.WorkTasks)
254:             {
255:                 if (task?.Status == TaskStatus.Running)
256:                 {
257:                     return false;
258:                 }
259:             }
260: 
261:             return true;
262:         }

